@Khang5687 you can add variants to your `opencode.json` config
```
"github-copilot": {
  "models": {
    "gpt-5.3-codex": {
      "modalities": {
        "input": ["text", "image"],
        "output": ["text"]
      },
     "variants": {
          "low": {
            "reasoningEffort": "low",
            "reasoningSummary": "auto",
            "include": ["reasoning.encrypted_content"]
          },
          "medium": {
            "reasoningEffort": "medium",
            "reasoningSummary": "auto",
            "include": ["reasoning.encrypted_content"]
          },
          "high": {
            "reasoningEffort": "high",
            "reasoningSummary": "auto",
            "include": ["reasoning.encrypted_content"]
          },
          "xhigh": {
            "reasoningEffort": "xhigh",
            "reasoningSummary": "auto",
            "include": ["reasoning.encrypted_content"]
          }
      } 
    }
  }
}
```

